import tomlkit
for s in ['a.b = 1\na.c = 2\n','[a]\nx = 1\n[a.b]\ny = 2\n','a = {x = 1, b = {y = 2}}\n']:
 d=tomlkit.parse(s)
 def show(c, n=0):
  for k,v in c.body:
   print(' '*n,repr(k),type(v).__name__, 'dotted', k.is_dotted() if k else None, 'trivia', getattr(v,'_trivia',None))
   if hasattr(v,'value') and hasattr(v.value,'body'): show(v.value,n+2)
 show(d); print('---')
